version: "1.0"
metadata:
  description: "Complete data pipeline specification for HubSpot CRM analytics platform"
  author: "Data Engineering Team"
  created_date: "2025-09-11"
  last_updated: "2025-09-11"
  pipeline_phases: ["staging_contract", "modeling_spec"]
  business_domain: "Customer Relationship Management (CRM)"
  source_system: "HubSpot"

# --------------------------------------------------------------------------- #
# PHASE 1: Defines the transformation from raw data to clean staging tables.  #
# --------------------------------------------------------------------------- #
staging_contract:
  purpose: "Transform raw HubSpot data into clean, validated staging tables with standardized data types, consistent formatting, and data quality validation. This phase ensures data integrity and prepares datasets for business logic application."

  quality_actions:
    correct:
      description: "Automatically fix deterministic format issues such as email casing, whitespace trimming, and standardized date formats"
      examples: ["LOWER(TRIM(email))", "standardize timezone formats", "normalize phone numbers"]

    delete_row:
      description: "Remove entire row when records contain severe data quality issues that make them unusable downstream."
      examples: ["Explicitly marked for deletion", "Confirmed duplicates", "Invalid primary keys", "Essential business attributes contain irrecoverable errors"]

    nullify_field:
      description: "Set invalid field values to NULL when the field is non-critical and record can still be useful"
      examples: ["malformed optional URLs", "invalid secondary contact information", "corrupted metadata fields"]

  tables:
[Per-table sections of the data contract are omitted here. The sections relevant to each review appear under "Relevant specification and documentation".]
modeling_spec:
  purpose: "Transform staging data into business-ready models that support marketing analytics, sales performance management, and customer service operations. Apply sophisticated business logic including customer lifecycle analysis, sales forecasting, and marketing attribution."

  design_principles:
    intermediate_purpose: "Create reusable, business-centric data models that encapsulate complex calculations and serve as building blocks for multiple downstream marts"
    sales_purpose: "Provide sales analysis-ready tables optimized for deal tracking, sales performance, and revenue forecasting"
    service_purpose: "Provide service analysis-ready tables for support operations, SLA tracking, and customer satisfaction"
    marketing_purpose: "Provide marketing analysis-ready tables for campaign performance, lead scoring, and attribution"
    grain_importance: "Every model must have an explicitly defined grain (one row per X) to ensure data integrity and proper aggregation"
    modularity: "Models should be designed for reusability across multiple business domains"
    performance: "Complex calculations should be materialized in intermediate models to optimize mart performance"

  intermediate_models:
  marketing_models:
  sales_models:
  service_models:

```

