select
    cast(id as varchar) as company_id,
    property_name as company_name,
    property_description as description,
    case when property_industry in ('Technology','Healthcare','Finance','Manufacturing','Retail','Education','Government','Other','Consulting','Real Estate','Hospitality') then property_industry else null end as industry,
    property_address as address,
    property_address_2 as address_2,
    property_city as city,
    property_state as state,
    property_country as country,
    case when property_annualrevenue < 0 then 0 else try_cast(property_annualrevenue as decimal(18,2)) end as annual_revenue,
    try_strptime(substr(property_createdate, 1, 19), '%Y-%m-%d %H:%M:%S') as created_date,
    coalesce(is_deleted,false) as is_company_deleted,
    cast(null as timestamptz) as _fivetran_synced
from raw.company_data
where id is not null and try_strptime(substr(property_createdate, 1, 19), '%Y-%m-%d %H:%M:%S') >= timestamp '2000-01-01' and try_strptime(substr(property_createdate, 1, 19), '%Y-%m-%d %H:%M:%S') <= current_timestamp
    try_strptime(substr(nullif(property_closed_date,''), 1, 19), '%Y-%m-%d %H:%M:%S') as closed_date,
    try_strptime(substr(property_first_agent_reply_date, 1, 19), '%Y-%m-%d %H:%M:%S') as first_agent_reply_date,
    try_cast(is_deleted as boolean) as is_ticket_deleted,
    cast(null as timestamptz) as _fivetran_synced
from raw.ticket_data
where id is not null and try_strptime(substr(property_createdate, 1, 19), '%Y-%m-%d %H:%M:%S') is not null


